const input = $input.first().json.body;
if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Send one estimate as a JSON object.');
const {estimate_id, revision, scope, total_cents} = input;
if (typeof estimate_id !== 'string' || !/^[A-Za-z0-9_-]{1,50}$/.test(estimate_id)) throw new Error('Use a 1–50 character estimate ID with letters, digits, dashes or underscores.');
if (!Number.isInteger(revision) || revision < 1 || revision > 2147483647) throw new Error('Supply a positive integer revision.');
if (typeof scope !== 'string' || !scope.trim() || scope.trim().length > 220) throw new Error('Describe the work in 1–220 characters.');
if (!Number.isInteger(total_cents) || total_cents < 1 || total_cents > 2147483647) throw new Error('Supply the USD total in positive whole cents.');
return [{json:{estimate_id, revision, scope:scope.trim(), total_cents}}];
